const assert=require('node:assert/strict'),{load}=require('./load-ts.cjs');const ps=load('lib/dailyPosts20261027.ts').DAILY_POSTS_20261027,news=load('lib/dailyNews20261027.ts').DAILY_NEWS_20261027;assert.equal(ps.length,5);assert.equal(news.length,1);const qs=ps.map(p=>p.content.filter(b=>b.type==='question'));assert(qs.every(q=>q.length===8));
